import Database from 'better-sqlite3';
import { existsSync, mkdirSync, statSync } from 'node:fs';
import { dirname } from 'node:path';

/**
 * Durable SQLite storage adapter implementing the Storage adapter shape:
 * {
 *   async initialState(id) -> { hardState?, confState?, snapshot?, entries? }
 *   async persistReady(id, ready) -> persist snapshot -> entries -> hardState (fsync before resolve)
 * }
 *
 * Notes:
 * - One DB file per node recommended (examples pass ./data/node-{id}.sqlite).
 * - Uses WAL + synchronous=FULL for durability barrier on COMMIT.
 * - Tail replacement on append (delete entries >= first new index, then insert).
 * - Compaction on snapshot (delete entries <= snapshot.index).
 */
export class SqliteStorage {
  /**
   * @param {Object} opts
   * @param {string} opts.file - path to sqlite file (e.g., ./data/node-1.sqlite)
   * @param {Record<string, string|number|boolean>} [opts.pragmas] - optional extra PRAGMA settings
   */
  constructor(opts = {}) {
    this.file = opts.file || ':memory:'; // default for tests
    this.pragmas = opts.pragmas || {};
    // Optional durability/config knobs (override defaults in open())
    this.journalMode = opts.journalMode;             // e.g. 'WAL' | 'DELETE'
    this.synchronous = opts.synchronous;             // e.g. 'FULL' | 'NORMAL' | 'OFF' | 2/1/0
    this.walAutocheckpoint = opts.walAutocheckpoint; // number of pages
    this.busyTimeout = opts.busyTimeout;             // ms
    this.foreignKeys = opts.foreignKeys;             // boolean

    // Optional lifecycle hook for co-located tables/schema initialization
    this.onOpen = typeof opts.onOpen === 'function' ? opts.onOpen : null;

    this.db = null;
    // Promise chain to serialize persistReady calls (defensive, drain loop is sequential)
    this._lock = Promise.resolve();
  }

  /**
   * Open the SQLite database and run migrations/PRAGMAs.
   */
  open() {
    if (this.db) return;

    if (this.file !== ':memory:') {
      const dir = dirname(this.file);
      if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    }

    const db = new Database(this.file, { fileMustExist: false });

    // Durability + performance PRAGMAs
    // Defaults: COMMIT is the durability barrier with synchronous=FULL and WAL.
    db.pragma('journal_mode = WAL');
    db.pragma('synchronous = FULL');
    db.pragma('wal_autocheckpoint = 1000');
    db.pragma('foreign_keys = ON');
    db.pragma('busy_timeout = 5000');

    // Explicit options override defaults if provided
    if (this.journalMode) db.pragma(`journal_mode = ${this.journalMode}`);
    if (this.synchronous != null) db.pragma(`synchronous = ${this.synchronous}`);
    if (this.walAutocheckpoint != null) db.pragma(`wal_autocheckpoint = ${this.walAutocheckpoint}`);
    if (this.foreignKeys != null) db.pragma(`foreign_keys = ${this.foreignKeys ? 'ON' : 'OFF'}`);
    if (this.busyTimeout != null) db.pragma(`busy_timeout = ${this.busyTimeout}`);

    // User-specified PRAGMAs last (override defaults if desired)
    if (this.pragmas && typeof this.pragmas === 'object') {
      for (const [k, v] of Object.entries(this.pragmas)) {
        db.pragma(`${k} = ${v}`);
      }
    }

    // Schema
    db.exec(`
      CREATE TABLE IF NOT EXISTS hard_state(
        id INTEGER PRIMARY KEY CHECK (id = 1),
        term INTEGER NOT NULL,
        vote TEXT,
        commit_index INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS entries(
        idx INTEGER PRIMARY KEY,
        term INTEGER NOT NULL,
        etype INTEGER NOT NULL,
        data BLOB,
        context BLOB
      );

      CREATE TABLE IF NOT EXISTS snapshot(
        id INTEGER PRIMARY KEY CHECK (id = 1),
        snap_index INTEGER NOT NULL,
        term INTEGER NOT NULL,
        conf_state TEXT,
        data BLOB,
        created_at INTEGER NOT NULL
      );
    `);

    this.db = db;

    // Invoke user hook to initialize co-located tables using the same DB file/handle
    try {
      if (this.onOpen) this.onOpen(db);
    } catch {
      // user hook error is not fatal to raft storage
    }
  }

  /**
   * Close the DB handle.
   */
  close() {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  /**
   * Return the underlying better-sqlite3 Database handle.
   * Consumers must not mutate raft-logic tables; intended for co-located app tables.
   */
  getDb() {
    return this._requireDb();
  }

  /**
   * Force a WAL checkpoint. mode: 'PASSIVE'|'FULL'|'RESTART'|'TRUNCATE' (default FULL)
   */
  checkpoint(mode = 'FULL') {
    const db = this._requireDb();
    try {
      db.pragma(`wal_checkpoint(${mode})`);
    } catch (e) {
      // ignore if not in WAL or not supported
    }
  }

  /**
   * VACUUM the database to reclaim free pages.
   */
  vacuum() {
    const db = this._requireDb();
    db.exec('VACUUM');
  }

  /**
   * Get or set a PRAGMA. If value is provided, sets; always returns current rows.
   */
  pragma(name, value) {
    const db = this._requireDb();
    if (typeof value !== 'undefined') {
      db.pragma(`${name} = ${value}`);
    }
    return db.pragma(name);
  }

  /**
   * Return storage stats and high watermarks for observability.
   */
  stats() {
    const db = this._requireDb();
    const rowMin = db.prepare('SELECT MIN(idx) AS minIdx FROM entries').get();
    const rowMax = db.prepare('SELECT MAX(idx) AS maxIdx FROM entries').get();
    const maxIdx = rowMax && rowMax.maxIdx != null ? Number(rowMax.maxIdx) : 0;
    const minIdx = rowMin && rowMin.minIdx != null ? Number(rowMin.minIdx) : 0;
    const lastTerm = maxIdx > 0 ? (db.prepare('SELECT term FROM entries WHERE idx = ?').get(maxIdx)?.term ?? 0) : 0;
    const snapRow = db.prepare('SELECT snap_index FROM snapshot WHERE id = 1').get();
    const snapIndex = snapRow ? Number(snapRow.snap_index) : 0;
    const hs = db.prepare('SELECT term, vote, commit_index FROM hard_state WHERE id = 1').get();
    const entryCount = db.prepare('SELECT COUNT(1) AS c FROM entries').get()?.c ?? 0;
    let fileSize = 0;
    if (this.file && this.file !== ':memory:' && existsSync(this.file)) {
      try { fileSize = statSync(this.file).size; } catch {}
    }
    return {
      minIndex: minIdx,
      lastIndex: maxIdx,
      lastTerm: Number(lastTerm),
      snapshotIndex: snapIndex,
      hardState: hs ? { term: Number(hs.term), vote: hs.vote != null ? String(hs.vote) : undefined, commit: Number(hs.commit_index) } : undefined,
      entryCount: Number(entryCount),
      fileSize,
    };
  }

  /**
   * Online backup to another sqlite file (uses better-sqlite3 Database#backup).
   */
  async backup(toFile) {
    const db = this._requireDb();
    if (typeof db.backup === 'function') {
      await db.backup(toFile);
    } else {
      throw new Error('backup() not supported by installed better-sqlite3 version');
    }
  }

  _requireDb() {
    if (!this.db) throw new Error('SqliteStorage: call open() before use');
    return this.db;
  }

  /**
   * Load latest snapshot, hard state, and any remaining entries after snapshot.index.
   * Return shape compatible with wasm JSON boundary. Current JS host ignores this
   * when creating the node; Phase 2 can wire this into bootstrap.
   */
  async initialState(_id) {
    const db = this._requireDb();
    const snap = db.prepare('SELECT snap_index AS "index", term, conf_state, data FROM snapshot WHERE id = 1').get();
    const hs = db.prepare('SELECT term, vote, commit_index FROM hard_state WHERE id = 1').get();

    const snapIndex = snap ? Number(snap.index) : 0;
    const ents = db
      .prepare('SELECT idx AS "index", term, etype AS entryType, data, context FROM entries WHERE idx > ? ORDER BY idx ASC')
      .all(snapIndex);

    const toBase64 = (buf) => (buf ? Buffer.from(buf).toString('base64') : undefined);
    const entries = ents.map((e) => ({
      index: String(e.index),
      term: String(e.term),
      entryType: e.entryType,
      data: e.data ? toBase64(e.data) : undefined,
      context: e.context ? toBase64(e.context) : undefined,
    }));

    const res = {};
    if (hs) {
      res.hardState = {
        term: String(hs.term),
        vote: hs.vote != null ? String(hs.vote) : undefined,
        commit: String(hs.commit_index),
      };
    }
    if (snap && Number(snap.index) > 0) {
      res.snapshot = {
        metadata: {
          index: String(snap.index),
          term: String(snap.term),
          confState: snap.conf_state ? JSON.parse(snap.conf_state) : undefined,
        },
        data: snap.data ? toBase64(snap.data) : undefined,
      };
    }
    if (entries.length) res.entries = entries;
    return res;
  }

  /**
   * Persist Ready atomically and durably:
   * - snapshot (compaction: delete entries <= snapshot.index)
   * - entries (tail replace: delete entries >= firstNew, then insert)
   * - hardState
   */
  async persistReady(_id, ready) {
    const db = this._requireDb();
    // serialize persists defensively
    this._lock = this._lock.then(() => this._persistReady(db, ready));
    return this._lock;
  }

  _persistReady(db, ready) {
    const now = Date.now();

    const begin = db.prepare('BEGIN IMMEDIATE');
    const commit = db.prepare('COMMIT');
    const rollback = db.prepare('ROLLBACK');

    const delEntriesGte = db.prepare('DELETE FROM entries WHERE idx >= ?');
    const delEntriesLe = db.prepare('DELETE FROM entries WHERE idx <= ?');
    const insEntry = db.prepare('INSERT INTO entries (idx, term, etype, data, context) VALUES (?, ?, ?, ?, ?)');
    const upsertHardState = db.prepare(`
      INSERT INTO hard_state (id, term, vote, commit_index, updated_at)
      VALUES (1, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE
      SET term = excluded.term, vote = excluded.vote, commit_index = excluded.commit_index, updated_at = excluded.updated_at
    `);
    const upsertSnapshot = db.prepare(`
      INSERT INTO snapshot (id, snap_index, term, conf_state, data, created_at)
      VALUES (1, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE
      SET snap_index = excluded.snap_index, term = excluded.term, conf_state = excluded.conf_state, data = excluded.data, created_at = excluded.created_at
    `);

    const b64ToBuf = (b) => (typeof b === 'string' ? Buffer.from(b, 'base64') : null);

    try {
      begin.run();

      // 1) Snapshot (compaction)
      const snap = ready && ready.snapshot;
      if (snap && snap.metadata && Number(snap.metadata.index) > 0) {
        const sidx = Number(snap.metadata.index);
        const sterm = Number(snap.metadata.term);
        const confStateJson = snap.metadata.confState ? JSON.stringify(snap.metadata.confState) : null;
        const sdata = snap.data ? b64ToBuf(snap.data) : null;

        upsertSnapshot.run(sidx, sterm, confStateJson, sdata, now);
        delEntriesLe.run(sidx);
      }

      // 2) Entries (tail replace)
      if (Array.isArray(ready?.entries) && ready.entries.length) {
        const firstIdx = Number(ready.entries[0].index);
        delEntriesGte.run(firstIdx);
        for (const e of ready.entries) {
          const idx = Number(e.index);
          const term = Number(e.term);
          const typ = Number(e.entryType ?? e.type ?? e.typ ?? 0);
          const data = e.data ? b64ToBuf(e.data) : null;
          const context = e.context ? b64ToBuf(e.context) : null;
          insEntry.run(idx, term, typ, data, context);
        }
      }

      // 3) HardState (term, vote, commit)
      if (ready && ready.hardState) {
        const hs = ready.hardState;
        const term = Number(hs.term ?? 0);
        const vote = hs.vote != null ? String(hs.vote) : null;
        const commitIdx = Number(hs.commit ?? 0);
        upsertHardState.run(term, vote, commitIdx, now);
      }

      // Durability barrier
      commit.run();
    } catch (err) {
      try {
        rollback.run();
      } catch {
        // ignore rollback failure
      }
      throw err;
    }
  }
}

export default SqliteStorage;
